-- Dedicated checkpoint subsystem. No checkpoint value writes to daily logs.
create table public.cp_profiles(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,config jsonb not null,approved_by uuid references auth.users,approved_at timestamptz,created_at timestamptz not null default now(),created_by uuid not null default auth.uid());
create table public.cp_schedules(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,scope text not null check(scope in ('farm','shed','batch')),scope_id uuid not null references public.records,config jsonb not null,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null default auth.uid());
create table public.cp_instances(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,batch_id uuid not null references public.records,schedule_id uuid references public.cp_schedules,schedule_revision int not null default 1,scheduled_at timestamptz not null,deadline_at timestamptz not null,escalate_at timestamptz not null,timezone text not null,snapshot jsonb not null,worker_id uuid not null references auth.users,manager_id uuid not null references auth.users,status text not null default 'upcoming' check(status in ('upcoming','due','completed','late','missed','cancelled')),escalated_at timestamptz,created_at timestamptz not null default now(),unique(schedule_id,schedule_revision,batch_id,scheduled_at));
create index cp_instances_batch_time on public.cp_instances(batch_id,scheduled_at);
create table public.cp_readings(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,batch_id uuid not null references public.records,instance_id uuid not null references public.cp_instances,request_id uuid not null,actor uuid not null default auth.uid() references auth.users,measured_at timestamptz not null,uploaded_at timestamptz not null default now(),updated_at timestamptz not null default now(),revision int not null default 1,payload jsonb not null,derived jsonb not null default '{}',profile_snapshot jsonb not null,unique(actor,request_id));
create index cp_readings_batch_time on public.cp_readings(batch_id,measured_at);
create table public.cp_alerts(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,batch_id uuid not null references public.records,instance_id uuid references public.cp_instances,rule_key text not null,severity text not null check(severity in ('information','warning','critical')),status text not null default 'open' check(status in ('open','acknowledged','resolved')),title text not null,why text not null,checks text not null,observed jsonb not null,thresholds jsonb not null,source text not null,assigned_to uuid references auth.users,manager_id uuid references auth.users,created_at timestamptz not null default now(),measurement_at timestamptz,updated_at timestamptz not null default now(),recheck_at timestamptz not null,escalated_at timestamptz,resolved_at timestamptz,resolution text,history jsonb not null default '[]');
create index cp_alerts_batch on public.cp_alerts(batch_id,status);
create table public.cp_rule_state(batch_id uuid not null references public.records,rule_key text not null,bad_count int not null default 0,good_count int not null default 0,event_key text,alert_id uuid references public.cp_alerts,primary key(batch_id,rule_key));
create table public.cp_actions(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,batch_id uuid not null references public.records,alert_id uuid not null references public.cp_alerts,actor uuid not null default auth.uid(),kind text not null,comment text not null,created_at timestamptz not null default now(),followup_id uuid references public.cp_instances);
create table public.cp_notifications(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,batch_id uuid not null references public.records,user_id uuid not null references auth.users,kind text not null,message text not null,entity_id uuid,created_at timestamptz not null default now(),read_at timestamptz,dedup_key text not null unique,push_status text not null default 'not_enabled',push_attempted_at timestamptz,push_error text);
create table public.cp_push_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,subscription jsonb not null,enabled boolean not null default true,updated_at timestamptz not null default now());
create unique index cp_push_endpoint on cp_push_subscriptions(user_id,(subscription->>'endpoint'));
create table public.cp_insights(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.organizations,batch_id uuid not null references public.records,actor uuid not null default auth.uid(),period_start timestamptz not null,period_end timestamptz not null,model text not null,input_hash text not null,content jsonb not null,created_at timestamptz not null default now());
create table public.cp_audit(id bigint generated always as identity primary key,org_id uuid,actor uuid,entity text not null,entity_id uuid,old_data jsonb,new_data jsonb,at timestamptz not null default now());
create table public.cp_private_settings(id boolean primary key default true check(id),value jsonb not null);
-- Access mirrors the existing farm/shed assignment model, with explicit batch/org identity.
create function public.cp_access(o uuid,b uuid,u uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from records r join memberships m on m.org_id=r.org_id and m.user_id=u where r.id=b and r.kind='batch' and r.org_id=o and (m.role in ('owner','manager','viewer','veterinarian') or m.role='worker' and exists(select 1 from assignments a where a.org_id=o and a.user_id=u and a.shed_id::text=r.data->>'shed')))
$$;
create function public.cp_staff(o uuid,b uuid) returns boolean language sql stable security definer set search_path=public as $$ select cp_access(o,b) and org_role(o) in ('owner','manager','worker','veterinarian') $$;
create function public.cp_admin(o uuid) returns boolean language sql stable security definer set search_path=public as $$ select org_role(o) in ('owner','manager') $$;
-- All clinical/scheduling writes are made through validated RPCs. No client table mutations.
do $$ declare t text;begin foreach t in array array['cp_profiles','cp_schedules','cp_instances','cp_readings','cp_alerts','cp_actions','cp_notifications','cp_push_subscriptions','cp_insights','cp_rule_state','cp_audit','cp_private_settings'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);end loop;end $$;
grant select on cp_profiles,cp_schedules,cp_instances,cp_readings,cp_alerts,cp_actions,cp_notifications,cp_push_subscriptions,cp_insights,cp_audit to authenticated;
create policy cp_profiles_read on cp_profiles for select to authenticated using(org_role(org_id) is not null);
create policy cp_schedules_read on cp_schedules for select to authenticated using(cp_admin(org_id) or exists(select 1 from records b where b.org_id=cp_schedules.org_id and b.kind='batch' and cp_access(b.org_id,b.id) and (scope='batch' and scope_id=b.id or scope='shed' and scope_id::text=b.data->>'shed' or scope='farm' and scope_id::text=b.data->>'farm')));
do $$ declare t text;begin foreach t in array array['cp_instances','cp_readings','cp_alerts','cp_actions','cp_insights'] loop execute format('create policy %I on public.%I for select to authenticated using(public.cp_access(org_id,batch_id))',t||'_read',t);end loop;end $$;
create policy cp_notifications_read on cp_notifications for select to authenticated using(user_id=auth.uid() and cp_access(org_id,batch_id));
create policy cp_subscriptions_read on cp_push_subscriptions for select to authenticated using(user_id=auth.uid());
create policy cp_audit_read on cp_audit for select to authenticated using(org_role(org_id) in ('owner','manager','veterinarian'));
grant all on cp_profiles,cp_schedules,cp_instances,cp_readings,cp_alerts,cp_actions,cp_notifications,cp_push_subscriptions,cp_insights,cp_rule_state,cp_audit,cp_private_settings to service_role;
grant usage,select on sequence cp_audit_id_seq to service_role;
create function public.cp_audit_change() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into cp_audit(org_id,actor,entity,entity_id,old_data,new_data) values(coalesce(new.org_id,old.org_id),auth.uid(),TG_TABLE_NAME,coalesce(new.id,old.id),case when TG_OP='INSERT' then null else to_jsonb(old) end,case when TG_OP='DELETE' then null else to_jsonb(new) end);return coalesce(new,old);end $$;
do $$ declare t text;begin foreach t in array array['cp_profiles','cp_schedules','cp_instances','cp_readings','cp_alerts','cp_actions','cp_insights'] loop execute format('create trigger cp_audit after insert or update or delete on public.%I for each row execute function cp_audit_change()',t);end loop;end $$;
create function public.cp_save_profile(o uuid,c jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare n uuid;begin if not cp_admin(o) then raise exception 'Only organization admins may approve management profiles';end if;if jsonb_typeof(c->'bands')<>'array' or jsonb_array_length(c->'bands')=0 or nullif(c->>'source','') is null or nullif(c->>'version','') is null or nullif(c->>'effectiveDate','') is null then raise exception 'Versioned source and age bands are required';end if;insert into cp_profiles(org_id,config,approved_by,approved_at) values(o,c,case when (c->>'approved')::boolean then auth.uid() end,case when (c->>'approved')::boolean then now() end) returning id into n;return n;end $$;
create function public.cp_save_schedule(o uuid,c jsonb,s uuid default null,expected_revision int default null) returns uuid language plpgsql security definer set search_path=public as $$
declare p cp_profiles; r records; targetfarm records; m uuid; w uuid; n uuid; z text;
begin
 if not cp_admin(o) then raise exception 'Only organization admins can configure schedules';end if;
 select * into r from records where id=(c->>'scopeId')::uuid and org_id=o and kind=c->>'scope';if not found then raise exception 'Invalid farm/shed/batch scope';end if;
 select * into targetfarm from records where org_id=o and kind='farm' and id=case when r.kind='farm' then r.id else (r.data->>'farm')::uuid end;
 z=coalesce(targetfarm.data->>'timezone',r.data->>'timezone','Asia/Kolkata');perform now() at time zone z;
 c=jsonb_set(c,'{timezone}',to_jsonb(z));
 select * into p from cp_profiles where id=(c->>'profileId')::uuid and org_id=o;if not found or (coalesce((c->>'enabled')::boolean,false) and p.approved_at is null) then raise exception 'Enabled schedules require an approved profile';end if;
 w=(c->>'worker')::uuid;m=(c->>'manager')::uuid;
 if not exists(select 1 from memberships where org_id=o and user_id=w and role in ('owner','manager','worker')) or not exists(select 1 from memberships where org_id=o and user_id=m and role in ('owner','manager')) then raise exception 'Choose an organization worker and backup manager';end if;
 if exists(select 1 from memberships where org_id=o and user_id=w and role='worker') and (r.kind='farm' or not exists(select 1 from assignments where org_id=o and user_id=w and shed_id=case when r.kind='shed' then r.id else (r.data->>'shed')::uuid end)) then raise exception 'Worker needs a shed assignment; farm-wide defaults require an owner/manager until overridden per shed';end if;
 if jsonb_typeof(c->'times')<>'array' or jsonb_array_length(c->'times')=0 or (c->>'windowMinutes')::int not between 1 and 720 or (c->>'leadMinutes')::int not between 0 and 240 or (c->>'escalateMinutes')::int not between 1 and 1440 then raise exception 'Invalid timing configuration';end if;
 if s is null then insert into cp_schedules(org_id,scope,scope_id,config) values(o,c->>'scope',(c->>'scopeId')::uuid,c) returning id into n;
 else update cp_schedules set config=c,scope=c->>'scope',scope_id=(c->>'scopeId')::uuid,revision=revision+1,updated_at=now() where id=s and org_id=o and revision=expected_revision returning id into n;if n is null then raise exception 'Schedule changed: reload before saving';end if;update cp_instances set status='cancelled' where schedule_id=s and scheduled_at>now() and status in ('upcoming','due') and not exists(select 1 from cp_readings where instance_id=cp_instances.id);end if;return n;
end $$;
-- Queue only to active members who retain access. In-app storage is the fallback.
create function public.cp_notify(o uuid,b uuid,u uuid,k text,msg text,e uuid,d text) returns void language plpgsql security definer set search_path=public as $$ begin if u is not null and cp_access(o,b,u) then insert into cp_notifications(org_id,batch_id,user_id,kind,message,entity_id,dedup_key) values(o,b,u,k,msg,e,d) on conflict(dedup_key) do nothing;end if;end $$;
create function public.cp_generate(b uuid) returns void language plpgsql security definer set search_path=public as $$
declare br records; sc cp_schedules; p cp_profiles; dt date; tm text; stamp timestamptz; age int; z text; config jsonb; srev int;
begin
 select * into br from records where id=b and kind='batch';if not found or br.data->>'status'='Completed' then return;end if;
 perform pg_advisory_xact_lock(hashtextextended(b::text,715));
 for sc in select * from cp_schedules s where s.org_id=br.org_id and coalesce((s.config->>'enabled')::boolean,false) and (s.scope='batch' and s.scope_id=b or s.scope='shed' and s.scope_id::text=br.data->>'shed' or s.scope='farm' and s.scope_id::text=br.data->>'farm') and (coalesce((s.config->>'extra')::boolean,false) or not exists(select 1 from cp_schedules x where x.org_id=s.org_id and (x.config->>'enabled')::boolean and not coalesce((x.config->>'extra')::boolean,false) and ((x.scope='batch' and x.scope_id=b and s.scope<>'batch') or (x.scope='shed' and x.scope_id::text=br.data->>'shed' and s.scope='farm')))) loop
 z=sc.config->>'timezone';select * into p from cp_profiles where id=(sc.config->>'profileId')::uuid and org_id=br.org_id;if p.approved_at is null then continue;end if;
 config=sc.config||jsonb_build_object('profile',p.config,'profileId',p.id,'approvedBy',p.approved_by,'approvedAt',p.approved_at,'farmId',br.data->>'farm','shedId',br.data->>'shed','batchName',br.data->>'name');
 for dt in select g::date from generate_series(greatest((br.data->>'placement')::date,(sc.config->>'startDate')::date,(sc.created_at at time zone z)::date),least(coalesce((sc.config->>'endDate')::date,(now() at time zone z)::date+2),(now() at time zone z)::date+2),interval '1 day') g loop
 age=dt-(br.data->>'placement')::date+1;if age<coalesce((sc.config->>'fromDay')::int,1) or age>coalesce((sc.config->>'toDay')::int,100000) then continue;end if;
 for tm in select v from (select jsonb_array_elements_text(sc.config->'times') v where sc.config->>'intervalMinutes' is null union select to_char(time '00:00'+i*interval '1 minute','HH24:MI') from generate_series(0,1439,(sc.config->>'intervalMinutes')::int) i where sc.config->>'intervalMinutes' is not null) q loop
 stamp=(dt+tm::time) at time zone z;
 insert into cp_instances(org_id,batch_id,schedule_id,schedule_revision,scheduled_at,deadline_at,escalate_at,timezone,snapshot,worker_id,manager_id) values(br.org_id,b,sc.id,sc.revision,stamp,stamp+make_interval(mins=>(sc.config->>'windowMinutes')::int),stamp+make_interval(mins=>(sc.config->>'windowMinutes')::int+(sc.config->>'escalateMinutes')::int),z,config,(sc.config->>'worker')::uuid,(sc.config->>'manager')::uuid) on conflict do nothing;
 end loop;end loop;end loop;
end $$;
-- Read usable numeric evidence only. Ammonia estimates are rejected at submission.
create function public.cp_num(p jsonb,k text,est boolean default false) returns numeric language sql immutable set search_path=public as $$ select case when p#>>array['values',k,'value'] is not null and (p#>>array['values',k,'state']='measured' or est and p#>>array['values',k,'state']='estimated') then (p#>>array['values',k,'value'])::numeric end $$;
-- One active state per batch/rule; histories retain every distinct reading revision.
create function public.cp_observe(i public.cp_instances,r public.cp_readings,k text,sev text,title_ text,why_ text,checks_ text,obs jsonb,limits_ jsonb,bad boolean,recovered boolean) returns void language plpgsql security definer set search_path=public as $$
declare st cp_rule_state; al cp_alerts; event_ text; persistence_ int; recovery_ int; n uuid;
begin
 event_=r.id::text||':'||r.revision::text;insert into cp_rule_state(batch_id,rule_key) values(i.batch_id,k) on conflict do nothing;select * into st from cp_rule_state where batch_id=i.batch_id and rule_key=k for update;if st.event_key=event_ then return;end if;
 persistence_=greatest(1,least(10,coalesce((i.snapshot#>>'{profile,rules,persistenceCount}')::int,1)));recovery_=greatest(1,least(10,coalesce((i.snapshot#>>'{profile,rules,recoveryCount}')::int,2)));
 if st.alert_id is not null then select * into al from cp_alerts where id=st.alert_id;if al.status='resolved' then st.alert_id=null;st.bad_count=0;st.good_count=0;end if;end if;
 if bad then
 st.bad_count=st.bad_count+1;st.good_count=0;
 if sev='critical' or k like 'missing_%' or st.bad_count>=persistence_ then
 if st.alert_id is null then insert into cp_alerts(org_id,batch_id,instance_id,rule_key,severity,title,why,checks,observed,thresholds,source,assigned_to,manager_id,measurement_at,recheck_at,history) values(i.org_id,i.batch_id,i.id,k,sev,title_,why_,checks_,obs,limits_,coalesce(i.snapshot#>>'{profile,source}','Operational equipment/observation rule'),i.worker_id,i.manager_id,r.measured_at,now()+make_interval(mins=>coalesce((i.snapshot#>>'{profile,rules,responseMinutes}')::int,30)),jsonb_build_array(jsonb_build_object('readingId',r.id,'revision',r.revision,'measuredAt',r.measured_at,'observed',obs,'severity',sev))) returning id into st.alert_id;
 perform cp_notify(i.org_id,i.batch_id,i.worker_id,'alert',title_,st.alert_id,'alert:'||st.alert_id::text||':worker');if sev='critical' then perform cp_notify(i.org_id,i.batch_id,i.manager_id,'critical',title_,st.alert_id,'alert:'||st.alert_id::text||':manager');end if;
 else update cp_alerts set severity=case when severity='critical' or sev='critical' then 'critical' else sev end,observed=obs,thresholds=limits_,measurement_at=r.measured_at,updated_at=now(),history=history||jsonb_build_array(jsonb_build_object('readingId',r.id,'revision',r.revision,'measuredAt',r.measured_at,'observed',obs,'severity',sev)) where id=st.alert_id;end if;
 end if;
 else
 st.bad_count=0;
 if recovered and st.alert_id is not null and r.measured_at>al.measurement_at then st.good_count=st.good_count+1;else st.good_count=0;end if;
 if st.alert_id is not null and st.good_count>=recovery_ then update cp_alerts set status='resolved',resolved_at=now(),resolution='Recovery criteria met in '||recovery_||' distinct follow-up measurements.',updated_at=now(),history=history||jsonb_build_array(jsonb_build_object('recoveryReading',r.id,'measuredAt',r.measured_at,'observed',obs)) where id=st.alert_id;st.alert_id=null;st.good_count=0;end if;
 end if;
 update cp_rule_state set event_key=event_,bad_count=st.bad_count,good_count=st.good_count,alert_id=st.alert_id where batch_id=i.batch_id and rule_key=k;
end $$;
create function public.cp_derive(r public.cp_readings) returns jsonb language plpgsql security definer set search_path=public as $$
declare p jsonb=r.payload; prev cp_readings; st timestamptz; hours_ numeric; birds numeric; water_ numeric; feed_ numeric; good boolean=true; reason_ text=''; br records;
begin
 select * into br from records where id=r.batch_id;
 st=nullif(p->>'intervalStart','')::timestamptz;birds=nullif(p->>'openingBirds','')::numeric;feed_=cp_num(p,'feedAmount');water_=case when p->>'waterMode'='interval' then cp_num(p,'waterAmount') end;
 if p->>'waterMode'='meter' then select * into prev from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<r.measured_at and x.payload->>'meterId'=p->>'meterId' and x.payload->>'waterMode' in ('meter','meter_reset') and cp_num(x.payload,'waterAmount') is not null order by x.measured_at desc limit 1;if prev.id is not null and cp_num(p,'waterAmount')>=cp_num(prev.payload,'waterAmount') then water_=cp_num(p,'waterAmount')-cp_num(prev.payload,'waterAmount');if st is distinct from prev.measured_at then good=false;reason_='Meter interval differs from supplied feed/mortality interval; combined comparisons withheld.';end if;else water_=null;reason_='Meter baseline missing or decreased; record an explicit reset.';end if;end if;
 if p->>'waterMode'='meter_reset' then water_=null;reason_='Meter reset establishes a new baseline; no consumption is inferred.';end if;
 if st is null or st>=r.measured_at or birds is null or birds<=0 then good=false;reason_=reason_||' Verified opening birds and actual interval are required for rate comparisons.';end if;
 hours_=extract(epoch from(r.measured_at-st))/3600;
 if exists(select 1 from records x where x.batch_id=r.batch_id and x.kind='inventory' and (x.data->>'date')::date between (st at time zone coalesce(br.data->>'timezone','Asia/Kolkata'))::date and (r.measured_at at time zone coalesce(br.data->>'timezone','Asia/Kolkata'))::date) then good=false;reason_=reason_||' Inventory movement timing is unknown within this interval.';end if;
 if exists(select 1 from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<=r.measured_at and nullif(x.payload->>'intervalStart','')::timestamptz<r.measured_at and x.measured_at>st and (cp_num(x.payload,'feedAmount') is not null or cp_num(x.payload,'waterAmount') is not null or cp_num(x.payload,'deaths') is not null)) then good=false;reason_=reason_||' Overlapping checkpoint intervals; comparisons withheld.';end if;
 return jsonb_build_object('intervalStart',st,'hours',hours_,'openingBirds',birds,'waterConsumed',water_,'feedConsumed',feed_,'comparable',good,'limits',reason_,'feedRate',case when good then feed_/birds/hours_ end,'waterRate',case when good then water_/birds/hours_ end,'mortalityRate',case when good then cp_num(p,'deaths')/birds/hours_ end,'dailyTotals','Excluded: checkpoint entries never write to daily totals.');
end $$;
create function public.cp_evaluate(rid uuid) returns void language plpgsql security definer set search_path=public as $$
declare r cp_readings; i cp_instances; br records; band jsonb; profile jsonb; lim jsonb; rules jsonb; age int; k text; v numeric; rr jsonb; bad boolean; recovery_ boolean; sev text; temp_ numeric; rh numeric; nh numeric; co numeric; respiratory boolean; signals text[]; first_at timestamptz; prev cp_readings; df numeric; dw numeric; dm numeric; baseline_count int; lowfeed boolean=false; lowwater boolean=false; mortalitybad boolean=false; sources jsonb; n numeric;
begin
 select * into r from cp_readings where id=rid;select * into i from cp_instances where id=r.instance_id;select * into br from records where id=r.batch_id;
 perform pg_advisory_xact_lock(hashtextextended(r.batch_id::text,716));
 r.derived=cp_derive(r);update cp_readings set derived=r.derived where id=r.id;
 -- Backfilled readings remain in charts/audits, but cannot masquerade as a current recheck.
 if exists(select 1 from cp_readings x where x.batch_id=r.batch_id and x.measured_at>r.measured_at) then return;end if;
 profile=i.snapshot->'profile';lim=profile->'limits';rules=profile->'rules';age=(r.measured_at at time zone i.timezone)::date-(br.data->>'placement')::date+1;
 select x into band from jsonb_array_elements(profile->'bands') x where age>=(x->>'from')::int and (x->>'to' is null or age<=(x->>'to')::int) limit 1;
 signals=ARRAY(select jsonb_array_elements_text(r.payload->'signs'));respiratory=signals&&array['abnormal_breathing','coughing','sneezing'];
 temp_=cp_num(r.payload,'temperature',coalesce((rules->>'allowEstimated')::boolean,false));rh=cp_num(r.payload,'humidity',coalesce((rules->>'allowEstimated')::boolean,false));nh=cp_num(r.payload,'ammonia');co=cp_num(r.payload,'co2');
 for k in select jsonb_array_elements_text(i.snapshot->'required') loop
 bad=false;
 if k='waterPh' and exists(select 1 from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<r.measured_at and x.measured_at>r.measured_at-make_interval(hours=>coalesce((i.snapshot->>'phEveryHours')::int,24)) and cp_num(x.payload,'waterPh') is not null) then continue;end if;
 if k in ('temperature','humidity','ammonia','co2','waterTemperature','waterPh','waterAmount','feedAmount','deaths','culls','lux') then bad=cp_num(r.payload,k,coalesce((rules->>'allowEstimated')::boolean,false)) is null;elsif k='photo' then bad=jsonb_array_length(coalesce(r.payload->'photos','[]'))=0;else bad=coalesce(r.payload#>>array['states',k],'unknown') in ('unknown','not_measured','instrument_unavailable','');end if;
 perform cp_observe(i,r,'missing_'||k,'warning','Missing critical measurement: '||k,'A required check was not established; unknown is not zero.','Arrange a suitable instrument or safe access, ask the backup manager for help and remeasure.',jsonb_build_object('field',k,'reported',r.payload#>array['values',k],'access',r.payload->'access'),jsonb_build_object('required',true),bad,not bad);
 end loop;
 perform cp_observe(i,r,'access','critical','Unable to access shed','The shed condition has not been checked.','Contact the assigned manager and arrange safe access; do not assume the shed is normal.',jsonb_build_object('access',r.payload->'access','reason',r.payload->'accessReason'),'{}',r.payload->>'access'='unable_to_access',r.payload->>'access'='accessible');
 for k in select unnest(array['temperature','humidity']) loop
 v=case when k='temperature' then temp_ else rh end;rr=band->k;
 bad=v is not null and (v<(rr->>'warningMin')::numeric or v>(rr->>'warningMax')::numeric);recovery_=v is not null and v between (rr->>'recoveryMin')::numeric and (rr->>'recoveryMax')::numeric;sev=case when v<=(rr->>'criticalMin')::numeric or v>=(rr->>'criticalMax')::numeric then 'critical' else 'warning' end;
 perform cp_observe(i,r,k,sev,'Shed '||k||' outside approved age range','Environmental conditions can impair comfort and performance; interpret humidity and bird behavior together.','Check sensor placement, water availability, fans, heaters and cooling. For cold conditions retain necessary fresh air and consider ammonia before reducing ventilation.',jsonb_build_object('value',v,'unit',case when k='temperature' then '°C' else '%' end,'flockDay',age,'signs',signals),rr,coalesce(bad,false),coalesce(recovery_,false));
 end loop;
 perform cp_observe(i,r,'ammonia',case when nh>=(lim->>'ammoniaCritical')::numeric then 'critical' else 'warning' end,'High ammonia','Ammonia can irritate birds and indicate poor litter/air management.','Check measured ammonia, litter moisture, drinker leaks and fresh-air delivery; do not rely on smell.',jsonb_build_object('value',nh,'unit','ppm'),lim,coalesce(nh>=(lim->>'ammoniaWarning')::numeric,false),coalesce(nh<=(lim->>'ammoniaRecovery')::numeric,false));
 perform cp_observe(i,r,'co2',case when co>=(lim->>'co2Critical')::numeric then 'critical' else 'warning' end,'High carbon dioxide','Poor fresh-air supply or combustion can compromise air quality.','Check calibrated gas readings and ventilation/heaters with trained personnel; do not enter a suspected unsafe atmosphere.',jsonb_build_object('value',co,'unit','ppm'),lim,coalesce(co>=(lim->>'co2Warning')::numeric,false),coalesce(co<=(lim->>'co2Recovery')::numeric,false));
 v=cp_num(r.payload,'waterPh');perform cp_observe(i,r,'water_ph','warning','Water pH outside approved range','Water quality may affect consumption and treatment/vaccine handling.','Confirm the instrument, source water and approved water-quality plan. Do not add chemicals based only on this alert.',jsonb_build_object('value',v,'unit','pH'),lim,coalesce(v<(lim->>'phMin')::numeric or v>(lim->>'phMax')::numeric,false),coalesce(v between (lim->>'phMin')::numeric and (lim->>'phMax')::numeric,false));
 for k in select unnest(array['fans','ventilation','heating','cooling','waterSupply','feedSupply']) loop
 bad=r.payload#>>array['states',k] in ('failed','interrupted','unavailable','blocked');recovery_=r.payload#>>array['states',k] in ('ok','available','off_not_required');sev=case when k in ('fans','ventilation','waterSupply') then 'critical' else 'warning' end;
 perform cp_observe(i,r,'equipment_'||k,sev,k||' requires attention','Equipment or supply interruption can quickly affect flock welfare.','Check power, backup systems, flow and access. Contact the manager/technician and remeasure; do not reduce ventilation without checking air quality.',jsonb_build_object('reported',r.payload#>array['states',k]),jsonb_build_object('expected','operational/available or explicitly not required'),coalesce(bad,false),coalesce(recovery_,false));
 end loop;
 perform cp_observe(i,r,'litter','warning','Wet or caked litter','Moist litter may affect foot condition and ammonia.','Find leaks, condensation and drainage problems; follow approved litter management and ventilation practices.',jsonb_build_object('reported',r.payload#>'{states,litter}'),'{}',coalesce(r.payload#>>'{states,litter}' in ('wet','caked'),false),r.payload#>>'{states,litter}'='dry');
 perform cp_observe(i,r,'lighting','warning','Unexpected lighting deviation','Unplanned changes can disrupt feeding and rest.','Compare actual light status with the approved program; check timer/power safely before changing settings.',jsonb_build_object('lights',r.payload#>'{states,lights}','deviation',r.payload#>'{states,lightDeviation}'),'{}',r.payload#>>'{states,lightDeviation}'='yes',r.payload#>>'{states,lightDeviation}'='no');
 perform cp_observe(i,r,'behavior','warning','Abnormal bird distribution or distress','Persistent panting, huddling or abnormal breathing can reflect environmental or health concerns.','Check bird-level climate, air quality, water and equipment. Seek urgent veterinary review for severe breathing difficulty or continuing losses.',jsonb_build_object('distribution',r.payload#>'{states,distribution}','signs',signals),'{}',coalesce(signals&&array['panting','huddling','abnormal_breathing'],false) or coalesce(r.payload#>>'{states,distribution}' in ('huddling','crowding','avoiding_area'),false),not(signals&&array['panting','huddling','abnormal_breathing']) and r.payload#>>'{states,distribution}'='even');
 select * into prev from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<r.measured_at order by measured_at desc limit 1;
 bad=temp_ is not null and cp_num(prev.payload,'temperature') is not null and r.measured_at-prev.measured_at<=make_interval(mins=>(rules->>'rapidWindowMinutes')::int) and abs(temp_-cp_num(prev.payload,'temperature'))>=(rules->>'rapidTemperatureDelta')::numeric;
 perform cp_observe(i,r,'rapid_temperature','warning','Rapid temperature change','A sudden change can indicate equipment failure or a measurement problem.','Check sensor calibration/location, fan/heater transitions and bird response; assess air quality before changing ventilation.',jsonb_build_object('previous',cp_num(prev.payload,'temperature'),'current',temp_,'previousTime',prev.measured_at,'unit','°C'),jsonb_build_object('delta',rules->'rapidTemperatureDelta','minutes',rules->'rapidWindowMinutes'),coalesce(bad,false),temp_ is not null and cp_num(prev.payload,'temperature') is not null and not coalesce(bad,false));
 -- Compare only non-overlapping, similar-duration intervals, per verified opening bird/hour,
 -- within three age-days and the same local clock start-hour window. Never project partial data.
 select count(*),avg((x.derived->>'feedRate')::numeric),avg((x.derived->>'waterRate')::numeric),avg((x.derived->>'mortalityRate')::numeric) into baseline_count,df,dw,dm from (select x.* from cp_readings x where x.batch_id=r.batch_id and x.id<>r.id and x.measured_at<r.measured_at and x.measured_at>r.measured_at-interval '3 days' and (x.derived->>'comparable')::boolean and (x.derived->>'hours')::numeric between (r.derived->>'hours')::numeric*.75 and (r.derived->>'hours')::numeric*1.25 and abs(extract(hour from ((x.derived->>'intervalStart')::timestamptz at time zone i.timezone))-extract(hour from ((r.derived->>'intervalStart')::timestamptz at time zone i.timezone)))<=1 and x.profile_snapshot=i.snapshot->'profile' order by x.measured_at desc limit 3) x;
 if baseline_count>=3 and coalesce((r.derived->>'comparable')::boolean,false) then lowfeed=df>0 and (r.derived->>'feedRate')::numeric<df*(1-(rules->>'intakeDropPct')::numeric/100);lowwater=dw>0 and (r.derived->>'waterRate')::numeric<dw*(1-(rules->>'intakeDropPct')::numeric/100);end if;
 update cp_readings set derived=derived||jsonb_build_object('baselineCount',baseline_count,'baselineFeedRate',df,'baselineWaterRate',dw,'baselineLimits','Requires three matched intervals, clock window, age proximity, verified birds and no unknown inventory movements.') where id=r.id;
 perform cp_observe(i,r,'feed_intake','warning','Reduced interval feed intake','Matched-interval feed consumption per bird/hour fell below the configured recent baseline.','Verify measured consumption, interval boundaries, feeder access, wastage, light schedule and bird activity.',r.derived,jsonb_build_object('baselineRate',df,'dropPct',rules->'intakeDropPct','source','Own matched checkpoint intervals'),coalesce(lowfeed,false),baseline_count>=3 and (r.derived->>'feedRate')::numeric>=df*.95);
 perform cp_observe(i,r,'water_intake','warning','Reduced interval water intake','Matched-interval water consumption per bird/hour fell below the configured recent baseline.','Check meter/reset, actual interval, leaks, supply, nipple flow and temperature; never restrict drinking access.',r.derived,jsonb_build_object('baselineRate',dw,'dropPct',rules->'intakeDropPct','source','Own matched checkpoint intervals'),coalesce(lowwater,false),baseline_count>=3 and (r.derived->>'waterRate')::numeric>=dw*.95);
 n=cp_num(r.payload,'deaths');mortalitybad=coalesce((r.payload->>'openingBirds')::numeric>0 and n/(r.payload->>'openingBirds')::numeric*100>=(rules->>'mortalityCriticalPct')::numeric,false);
 perform cp_observe(i,r,'mortality',case when mortalitybad then 'critical' else 'warning' end,'Mortality requires investigation','New deaths crossed an approved action threshold or rose against matched intervals. Mortality does not identify a disease.','Contact the veterinarian promptly; check water, ventilation and equipment while arranging examination. Do not wait for another day or choose medicines from environmental readings.',jsonb_build_object('deaths',n,'openingBirds',r.payload->'openingBirds','interval',r.derived),rules,mortalitybad or coalesce(baseline_count>=3 and dm>0 and (r.derived->>'mortalityRate')::numeric>dm*1.5,false),n=0);
 perform cp_observe(i,r,'combined_heat','critical','High heat + humidity + panting','Interacting conditions can make heat loss difficult.','Check drinking water, airflow, fans and cooling immediately; evaluate humidity before adding evaporation. Seek veterinary assistance if distress persists.',jsonb_build_object('temperature',temp_,'humidity',rh,'signs',signals),band,coalesce(temp_>(band#>>'{temperature,warningMax}')::numeric and rh>(band#>>'{humidity,warningMax}')::numeric and 'panting'=any(signals),false),coalesce(temp_ between (band#>>'{temperature,recoveryMin}')::numeric and (band#>>'{temperature,recoveryMax}')::numeric and rh between (band#>>'{humidity,recoveryMin}')::numeric and (band#>>'{humidity,recoveryMax}')::numeric and not 'panting'=any(signals),false));
 perform cp_observe(i,r,'combined_air','critical','High ammonia + wet litter + poor ventilation','The combined air/litter findings require prompt corrective action.','Check ventilation failure and wet-litter/leak sources together; keep personnel safe and contact the manager.',jsonb_build_object('ammonia',nh,'litter',r.payload#>'{states,litter}','ventilation',r.payload#>'{states,ventilation}'),lim,coalesce(nh>=(lim->>'ammoniaWarning')::numeric and r.payload#>>'{states,litter}' in ('wet','caked') and r.payload#>>'{states,ventilation}'='failed',false),coalesce(nh<=(lim->>'ammoniaRecovery')::numeric and r.payload#>>'{states,litter}'='dry' and r.payload#>>'{states,ventilation}'='ok',false));
 perform cp_observe(i,r,'combined_intake','warning','Reduced feed and water intake together','Matched per-bird interval rates fell together.','Check access, supply interruptions, lighting, interval recording and flock behavior; discuss persistent reductions with the veterinarian.',r.derived,rules,coalesce(lowfeed and lowwater,false),baseline_count>=3 and not coalesce(lowfeed or lowwater,true));
 perform cp_observe(i,r,'combined_mortality','critical','Rising mortality + respiratory signs','Concurrent losses and breathing signs need urgent veterinary investigation, not a photo-only diagnosis.','Contact the company veterinarian immediately, check equipment and safe air supply, limit unnecessary shed-to-shed movements and follow local reporting guidance.',jsonb_build_object('deaths',n,'signs',signals),rules,coalesce((mortalitybad or baseline_count>=3 and (r.derived->>'mortalityRate')::numeric>dm*1.5) and respiratory,false),n=0 and not respiratory);
end $$;
create function public.cp_submit(b uuid,p jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare i cp_instances; r cp_readings; old_ cp_readings; rid uuid; k text; v jsonb; n numeric; measured_ timestamptz; existing uuid; profile_ jsonb; approvedage int;
begin
 select * into i from cp_instances where id=(p->>'instanceId')::uuid and batch_id=b;if not found or not cp_staff(i.org_id,b) or org_role(i.org_id)='veterinarian' then raise exception 'Checkpoint is not accessible for recording';end if;
 perform pg_advisory_xact_lock(hashtextextended(b::text,716));
 select id into existing from cp_readings where actor=auth.uid() and request_id=(p->>'requestId')::uuid;if existing is not null then return existing;end if;
 if i.status='cancelled' or exists(select 1 from records where id=b and data->>'status'='Completed') then raise exception 'Schedule changed or batch is completed. Keep draft and review with the manager.';end if;
 measured_=(p->>'measuredAt')::timestamptz;if measured_>now()+interval '5 minutes' or measured_<i.scheduled_at-make_interval(mins=>(i.snapshot->>'leadMinutes')::int) then raise exception 'Measurement time is in the future or before the checkpoint opens';end if;
 if p->>'access' not in ('accessible','unable_to_access') or p->>'access'='unable_to_access' and nullif(trim(p->>'accessReason'),'') is null then raise exception 'Record access status and reason';end if;
 if jsonb_typeof(p->'values')<>'object' or jsonb_typeof(p->'states')<>'object' then raise exception 'Readings required';end if;
 for k,v in select * from jsonb_each(p->'values') loop
 if k not in ('temperature','humidity','ammonia','co2','waterTemperature','waterPh','waterAmount','feedAmount','deaths','culls','lux') then raise exception 'Unknown measurement';end if;
 if v->>'state' not in ('measured','not_measured','instrument_unavailable','estimated') or v->>'method' not in ('manual','sensor','estimated') then raise exception 'Measurement provenance required';end if;
 if v->>'value' is not null then n=(v->>'value')::numeric;if n<0 and k<>'temperature' or k='temperature' and n not between -10 and 60 or k='humidity' and n>100 or k='waterPh' and n>14 or k='ammonia' and n>500 or k='co2' and n>100000 or k in ('deaths','culls') and mod(n,1)<>0 then raise exception 'Invalid numeric reading';end if;end if;
 if v->>'state'='measured' and v->>'value' is null or v->>'state' in ('not_measured','instrument_unavailable') and v->>'value' is not null then raise exception 'Missing is not zero';end if;
 if k='ammonia' and (v->>'state'='estimated' or v->>'method'='estimated') then raise exception 'Ammonia must not be estimated from smell or images';end if;
 end loop;
 if jsonb_array_length(coalesce(p->'photos','[]'))>6 then raise exception 'Maximum six evidence photos';end if;
 for k in select jsonb_array_elements_text(coalesce(p->'photos','[]')) loop if k not like i.org_id::text||'/'||b::text||'/%' or k like '%..%' or array_length(string_to_array(k,'/'),1)<>3 then raise exception 'Photo outside authorized batch';end if;end loop;
 if nullif(p->>'intervalStart','')::timestamptz>=measured_ then raise exception 'Invalid interval';end if;
 profile_=i.snapshot->'profile';
 if p->>'readingId' is not null then
 select * into old_ from cp_readings where id=(p->>'readingId')::uuid and batch_id=b and instance_id=i.id;if not found or old_.revision<>(p->>'revision')::int or not(cp_admin(i.org_id) or old_.actor=auth.uid()) then raise exception 'Reading changed or correction is not permitted';end if;
 update cp_readings set payload=p,measured_at=measured_,revision=revision+1,updated_at=now() where id=old_.id returning id into rid;
 else insert into cp_readings(org_id,batch_id,instance_id,request_id,measured_at,payload,profile_snapshot) values(i.org_id,b,i.id,(p->>'requestId')::uuid,measured_,p,profile_) returning id into rid;end if;
 perform cp_evaluate(rid);
 -- A correction invalidates downstream rate derivations; recalculate in actual measurement order.
 for r in select * from cp_readings where batch_id=b and measured_at>measured_ order by measured_at loop update cp_readings set derived=cp_derive(r) where id=r.id;end loop;
 return rid;
end $$;
create function public.cp_tick_batch(b uuid) returns void language plpgsql security definer set search_path=public as $$
declare i cp_instances; r cp_readings; a cp_alerts; alertid uuid; state_ text; first_ timestamptz;
begin
 perform cp_generate(b);
 for i in select * from cp_instances where batch_id=b and status<>'cancelled' and scheduled_at<now()+interval '1 day' for update skip locked loop
 select * into r from cp_readings where instance_id=i.id and payload->>'access'='accessible' order by measured_at desc limit 1;
 state_=case when r.id is not null then case when r.measured_at>i.deadline_at then 'late' else 'completed' end when now()>i.escalate_at then 'missed' when now()>i.deadline_at then 'late' when now()>=i.scheduled_at-make_interval(mins=>(i.snapshot->>'leadMinutes')::int) then 'due' else 'upcoming' end;
 if state_<>i.status then update cp_instances set status=state_ where id=i.id;end if;
 if r.id is not null then update cp_alerts set status='resolved',resolved_at=now(),resolution='The checkpoint received an actual measurement. Late measurement/upload timestamps remain visible.',updated_at=now() where instance_id=i.id and rule_key='missed:'||i.id::text and status<>'resolved';continue;end if;
 if state_='due' then perform cp_notify(i.org_id,b,i.worker_id,'checkpoint_due','Checkpoint due: '||to_char(i.scheduled_at at time zone i.timezone,'YYYY-MM-DD HH24:MI')||' '||i.timezone,i.id,'due:'||i.id::text);end if;
 if now()>i.deadline_at then
 perform cp_notify(i.org_id,b,i.worker_id,'checkpoint_late','Checkpoint completion window has passed. Record actual measurement time or an access reason.',i.id,'late:'||i.id::text);
 if not exists(select 1 from cp_alerts where rule_key='missed:'||i.id::text) then
 insert into cp_alerts(org_id,batch_id,instance_id,rule_key,severity,title,why,checks,observed,thresholds,source,assigned_to,manager_id,recheck_at) values(i.org_id,b,i.id,'missed:'||i.id::text,'warning','Overdue / missed checkpoint','The scheduled shed condition has not been established.','Ask the worker or backup manager to check the shed, preserve actual times and submit a measurement or safe-access reason.',jsonb_build_object('scheduledAt',i.scheduled_at,'deadline',i.deadline_at),jsonb_build_object('completionWindow',i.snapshot->'windowMinutes','escalationDelay',i.snapshot->'escalateMinutes'),'Configured checkpoint schedule',i.worker_id,i.manager_id,i.escalate_at);end if;
 end if;
 if now()>i.escalate_at and i.escalated_at is null then update cp_instances set escalated_at=now() where id=i.id;update cp_alerts set escalated_at=now() where instance_id=i.id and rule_key='missed:'||i.id::text;perform cp_notify(i.org_id,b,i.manager_id,'checkpoint_escalated','Missed checkpoint escalated to backup manager.',i.id,'escalate:'||i.id::text);end if;
 end loop;
 for a in select * from cp_alerts where batch_id=b and status<>'resolved' and escalated_at is null and recheck_at<now() for update skip locked loop
 if now()>a.recheck_at+make_interval(mins=>coalesce((select (snapshot#>>'{profile,rules,escalateMinutes}')::int from cp_instances where id=a.instance_id),30)) then update cp_alerts set escalated_at=now(),updated_at=now() where id=a.id;perform cp_notify(a.org_id,b,a.manager_id,'alert_escalated','Unresolved alert escalated: '||a.title,a.id,'escalated-alert:'||a.id::text);end if;end loop;
end $$;
create function public.cp_refresh(b uuid) returns void language plpgsql security definer set search_path=public as $$ declare o uuid;begin select org_id into o from records where id=b and kind='batch';if not cp_access(o,b) then raise exception 'Batch not accessible';end if;perform cp_tick_batch(b);end $$;
create function public.cp_tick_all() returns void language plpgsql security definer set search_path=public as $$ declare b uuid;begin for b in select distinct r.id from records r join cp_schedules s on s.org_id=r.org_id where r.kind='batch' and coalesce(r.data->>'status','Active')<>'Completed' and (s.config->>'enabled')::boolean loop perform cp_tick_batch(b);end loop;end $$;
create function public.cp_extra(b uuid,scheduled timestamptz,reason_ text,base_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare i cp_instances; n uuid;begin select * into i from cp_instances where batch_id=b and (id=base_id or base_id is null) and status<>'cancelled' order by scheduled_at desc limit 1;if not found or not cp_staff(i.org_id,b) then raise exception 'Batch/checkpoint not accessible';end if;if length(trim(reason_))<5 or scheduled<now()-interval '5 minutes' or scheduled>now()+interval '7 days' then raise exception 'Reason and a near-term follow-up time required';end if;insert into cp_instances(org_id,batch_id,scheduled_at,deadline_at,escalate_at,timezone,snapshot,worker_id,manager_id) values(i.org_id,b,scheduled,scheduled+make_interval(mins=>(i.snapshot->>'windowMinutes')::int),scheduled+make_interval(mins=>(i.snapshot->>'windowMinutes')::int+(i.snapshot->>'escalateMinutes')::int),i.timezone,i.snapshot||jsonb_build_object('extraReason',reason_),i.worker_id,i.manager_id) returning id into n;return n;end $$;
create function public.cp_alert_action(aid uuid,kind_ text,comment_ text,assignee uuid default null,followup timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$
declare a cp_alerts; n uuid; f uuid;
begin select * into a from cp_alerts where id=aid for update;if not found or not cp_staff(a.org_id,a.batch_id) then raise exception 'Alert not accessible';end if;
 if kind_ not in ('acknowledge','assign','comment','corrective_action','override') or length(trim(comment_))<3 then raise exception 'Action and explanatory comment required';end if;
 if kind_='acknowledge' then update cp_alerts set status=case when status='open' then 'acknowledged' else status end,updated_at=now() where id=aid;
 elsif kind_='assign' then if not cp_admin(a.org_id) or not cp_access(a.org_id,a.batch_id,assignee) then raise exception 'Admin must choose an authorized assignee';end if;update cp_alerts set assigned_to=assignee,updated_at=now() where id=aid;
 elsif kind_='override' then if org_role(a.org_id) not in ('owner','manager','veterinarian') or length(trim(comment_))<20 then raise exception 'Authorized override requires a detailed justification';end if;update cp_alerts set status='resolved',resolution='Authorized override: '||comment_,resolved_at=now(),updated_at=now() where id=aid;
 elsif kind_='corrective_action' then if followup is null then raise exception 'Corrective actions require a follow-up measurement deadline';end if;f=cp_extra(a.batch_id,followup,'Recheck: '||a.title,a.instance_id);update cp_alerts set recheck_at=followup,updated_at=now() where id=aid;end if;
 insert into cp_actions(org_id,batch_id,alert_id,kind,comment,followup_id) values(a.org_id,a.batch_id,aid,kind_,comment_,f) returning id into n;return n;
end $$;
create function public.cp_mark_notification(n uuid) returns void language plpgsql security definer set search_path=public as $$ begin update cp_notifications set read_at=now() where id=n and user_id=auth.uid() and cp_access(org_id,batch_id);end $$;
create function public.cp_push_save(s jsonb) returns void language plpgsql security definer set search_path=public as $$ declare endpoint_ text=s->>'endpoint';begin if auth.uid() is null then raise exception 'Sign in required';end if;if endpoint_ !~ '^https://(fcm.googleapis.com|updates.push.services.mozilla.com|web.push.apple.com|[a-zA-Z0-9.-]+\.notify.windows.com)/' or length(endpoint_)>2500 or nullif(s#>>'{keys,p256dh}','') is null or nullif(s#>>'{keys,auth}','') is null then raise exception 'Unsupported or invalid push endpoint';end if;insert into cp_push_subscriptions(user_id,subscription) values(auth.uid(),s) on conflict(user_id,(subscription->>'endpoint')) do update set subscription=excluded.subscription,enabled=true,updated_at=now();end $$;
create function public.cp_push_disable() returns void language plpgsql security definer set search_path=public as $$ begin update cp_push_subscriptions set enabled=false,updated_at=now() where user_id=auth.uid();end $$;
create function public.cp_push_public() returns text language sql stable security definer set search_path=public as $$ select value->>'vapidPublic' from cp_private_settings where id $$;
create function public.cp_save_insight(b uuid,start_ timestamptz,end_ timestamptz,model_ text,hash_ text,content_ jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare o uuid;n uuid;begin select org_id into o from records where id=b and kind='batch';if not cp_staff(o,b) then raise exception 'Not accessible';end if;insert into cp_insights(org_id,batch_id,period_start,period_end,model,input_hash,content) values(o,b,start_,end_,model_,hash_,content_) returning id into n;return n;end $$;
-- Internal functions are not callable through the anonymous/authenticated RPC surface.
do $$ declare f record;begin for f in select p.oid::regprocedure sig,p.proname name from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'cp_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);if f.name in ('cp_access','cp_staff','cp_admin','cp_save_profile','cp_save_schedule','cp_submit','cp_refresh','cp_extra','cp_alert_action','cp_mark_notification','cp_push_save','cp_push_disable','cp_push_public','cp_save_insight') then execute format('grant execute on function %s to authenticated',f.sig);end if;end loop;end $$;
grant execute on function cp_tick_all(),cp_access(uuid,uuid,uuid) to service_role;
